using System.Text; var builder = WebApplication.CreateBuilder(args); builder.Services.AddHttpClient(); var app = builder.Build(); var cu = Environment.GetEnvironmentVariable("CATALOG_URL") ?? "http://catalog-service:8080"; var lu = Environment.GetEnvironmentVariable("LOAN_URL") ?? "http://loan-service:8080"; app.MapGet("/health", () => Results.Ok(new { Status = "Gateway running" })); app.MapGet("/api/books", async (IHttpClientFactory f) => Results.Content(await f.CreateClient().GetStringAsync($"{cu}/books"), "application/json")); app.MapPost("/api/books", async (HttpRequest req, IHttpClientFactory f) => { using var r = new StreamReader(req.Body); var res = await f.CreateClient().PostAsync($"{cu}/books", new StringContent(await r.ReadToEndAsync(), Encoding.UTF8, "application/json")); return Results.Content(await res.Content.ReadAsStringAsync(), "application/json", statusCode: (int)res.StatusCode); }); app.MapGet("/api/loans", async (IHttpClientFactory f) => Results.Content(await f.CreateClient().GetStringAsync($"{lu}/loans"), "application/json")); app.MapPost("/api/loans", async (HttpRequest req, IHttpClientFactory f) => { using var r = new StreamReader(req.Body); var res = await f.CreateClient().PostAsync($"{lu}/loans", new StringContent(await r.ReadToEndAsync(), Encoding.UTF8, "application/json")); return Results.Content(await res.Content.ReadAsStringAsync(), "application/json", statusCode: (int)res.StatusCode); }); app.Run();
